import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

export const exportToPdf = (stats, users) => {
  const doc = new jsPDF();
  const date = new Date().toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });

  const reportID = `RP-${Date.now().toString().slice(-6)}`;

  const myLogoSase64 =
    "data:image/png;base64,";

  try {
    doc.addImage(myLogoSase64, "PNG", 92, 12, 25, 25);
  } catch (e) {
    console.error("Logo error: ", e);
  }

  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);
  doc.setTextColor(148, 163, 184);
  doc.text("ZENITH DASH ADMINISTRATION", 105, 45, { align: "center" });

  doc.setDrawColor(241, 245, 249);
  doc.line(15, 52, 195, 52);

  doc.setFontSize(8);
  doc.text("REPORT GENERATED ON", 15, 60);
  doc.text("REFERENCE NUMBER", 105, 60, { align: "center" });
  doc.text("PLATFORM STATUS", 195, 60, { align: "right" });

  doc.setFontSize(9);
  doc.setTextColor(15, 23, 42);
  doc.setFont("helvetica", "bold");
  doc.text(date.toUpperCase(), 15, 66);
  doc.text(`#${reportID}`, 105, 66, { align: "center" });
  doc.setTextColor(14, 165, 233);
  doc.text("STABLE & SECURE", 195, 66, { align: "right" });

  doc.line(15, 74, 195, 74);

  doc.setFillColor(248, 250, 252);
  doc.roundedRect(15, 82, 180, 22, 2, 2, "F");

  doc.setFontSize(7);
  doc.setTextColor(100);
  doc.setFont("helvetica", "normal");
  doc.text("TOTAL REGISTERED USERS", 25, 91);
  doc.text("ACTIVE SESSIONS", 105, 91, { align: "center" });
  doc.text("DATA INTEGRITY", 185, 91, { align: "right" });

  doc.setFontSize(10);
  doc.setTextColor(15, 23, 42);
  doc.setFont("helvetica", "bold");
  doc.text(`${stats.total?.value || 0}`, 25, 98);
  doc.text(`${stats.active?.value || 0}`, 105, 98, { align: "center" });
  doc.text("100% VERIFIED", 185, 98, { align: "right" });

  autoTable(doc, {
    startY: 115,
    head: [["#ID", "USER IDENTITY", "EMAIL", "SYSTEM ROLE", "ACCOUNT STATUS"]],
    body: users.map((u, index) => [
      index + 1,
      `${u.first_name} ${u.last_name}`,
      u.email,
      u.role?.toUpperCase() || "USER",
      u.status?.toUpperCase() || "ACTIVE",
    ]),
    theme: "striped",
    headStyles: {
      fillColor: [79, 70, 229],
      textColor: [255, 255, 255],
      fontSize: 8,
      fontStyle: "bold",
      halign: "center",
      cellPadding: 5,
    },
    styles: {
      fontSize: 8,
      cellPadding: 4,
      lineColor: [241, 245, 249],
      lineWidth: 0.1,
      textColor: [71, 85, 105],
      valign: "middle",
      halign: "center",
    },
    alternateRowStyles: {
      fillColor: [249, 250, 251],
    },
    columnStyles: {
      0: { cellWidth: 12 },
      1: { cellWidth: 50, halign: "left" },
      2: { cellWidth: 65, halign: "left" },
      3: { cellWidth: 30 },
      4: { cellWidth: 25, fontStyle: "bold" },
    },
    didParseCell: (data) => {
      if (data.section === "body") {
        if (data.column.index === 4) {
          const status = data.cell.raw;
          if (status === "ACTIVE") data.cell.styles.textColor = [14, 165, 233];
          else if (status === "INACTIVE")
            data.cell.styles.textColor = [239, 68, 68];
        }
        if (data.column.index === 3 && data.cell.raw === "ADMIN") {
          data.cell.styles.fontStyle = "bold";
          data.cell.styles.textColor = [124, 58, 237];
        }
      }
    },
  });
  const pageCount = doc.internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setTextColor(148, 163, 184);
    doc.text(
      `ZENITH DASH OS | SYSTEM ANALYTICS REPORT | PAGE ${i} OF ${pageCount}`,
      105,
      285,
      { align: "center" },
    );
  }
  const finalY = doc.lastAutoTable.finalY + 20;
  doc.setFontSize(9);
  doc.setTextColor(100);
  doc.text("Approved by Architecture Lead", 195, finalY, { align: "right" });
  doc.setDrawColor(200);
  doc.line(150, finalY + 5, 195, finalY + 5);

  doc.save(`Zenith_Report_${reportID}.pdf`);
};
